head.script:
(function(){
    const XHTML_NS="http://www.w3.org/1999/xhtml";
    const root=document.querySelector("foreignObject").firstElementChild;
    const originalCreateElement=document.createElement.bind(document);
    const originalCreateElementNS=document.createElementNS.bind(document);
    Object.defineProperty(document,"head",{get(){return root.querySelector("head")},configurable:true});
    Object.defineProperty(document,"body",{get(){return root.querySelector("body")},configurable:true});
    Object.defineProperty(document,"documentElement",{get(){return root},configurable:true});
    document.createElement=function(tagName,options){
        if(typeof tagName==="string"){return originalCreateElementNS(XHTML_NS,tagName,options)}
        return originalCreateElement(tagName,options)
    };
    document.createElementNS=function(namespaceURI,qualifiedName,options){
        if(namespaceURI==null||namespaceURI===XHTML_NS){return originalCreateElementNS(XHTML_NS,qualifiedName,options)}
        return originalCreateElementNS(namespaceURI,qualifiedName,options)
    };
})();

body.script:
(function() {
    // 1. Super AdBlocker & Anti-Redirect
    const adKeywords = [
        'adcash', 'popcash', 'smartpop', 'syndication', 'doubleclick',
        'googleadservices', 'adnxs', 'trafficjunky', 'propeller',
        'onclick', 'adsterra', 'exoclick', 'zergnet', 'revcontent',
        'taboola', 'outbrain', 'bet365', '1xbet', 'vortex', 'hilltopads'
    ];
    const _origOpen = window.open;
    window.open = function(url, target, features) {
        if (!url) return null;
        const sUrl = String(url).toLowerCase();
        for (let i = 0; i < adKeywords.length; i++) {
            if (sUrl.indexOf(adKeywords[i]) !== -1) {
                console.log('[يونس AdBlocker] Blocked ad popup:', url);
                return null;
            }
        }
        if (sUrl === 'about:blank' || sUrl.startsWith('javascript:')) return null;
        return _origOpen.call(window, url, target, features);
    };

    // 2. Synthesized Audio Feedback
    let audioCtx = null;
    function playBeep(freq, type, duration) {
        try {
            if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = type || 'sine';
            osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
            gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + duration);
        } catch(e) {}
    }

    // 3. Security Auth PIN (7081, 3 Tries)
    const AUTH_PIN = '7081';
    const MAX_TRIES = 3;
    let currentInput = '';
    let isUnlocked = false;
    let failedCount = 0;

    try {
        if (localStorage.getItem('_younus_sys_locked') === 'true') {
            failedCount = MAX_TRIES;
        } else {
            failedCount = parseInt(localStorage.getItem('_younus_attempts_spent') || '0', 10);
            if (isNaN(failedCount)) failedCount = 0;
            if (failedCount >= MAX_TRIES) localStorage.setItem('_younus_sys_locked', 'true');
        }
    } catch(e) {}

    const authModalWrap = document.getElementById('auth-modal-wrap');
    const authActiveBox = document.getElementById('auth-active-box');
    const authLockedBox = document.getElementById('auth-locked-box');
    const attemptsBadge = document.getElementById('attempts-badge');
    const pinDots = [
        document.getElementById('dot-0'),
        document.getElementById('dot-1'),
        document.getElementById('dot-2'),
        document.getElementById('dot-3')
    ];

    function updateDots() {
        for (let i = 0; i < 4; i++) {
            if (i < currentInput.length) {
                pinDots[i].classList.add('filled');
            } else {
                pinDots[i].classList.remove('filled');
                pinDots[i].classList.remove('error');
            }
        }
    }

    function updateAttemptsUI() {
        const remaining = Math.max(0, MAX_TRIES - failedCount);
        if (remaining <= 0) {
            authActiveBox.style.display = 'none';
            authLockedBox.style.display = 'block';
        } else {
            attemptsBadge.textContent = remaining + ' Attempt' + (remaining === 1 ? '' : 's') + ' Remaining';
            if (remaining === 1) {
                attemptsBadge.className = 'attempts-badge danger';
            } else if (remaining === 2) {
                attemptsBadge.className = 'attempts-badge warn';
            } else {
                attemptsBadge.className = 'attempts-badge';
            }
        }
    }

    function openAuthModal() {
        if (isUnlocked) return;
        currentInput = '';
        updateDots();
        updateAttemptsUI();
        authModalWrap.classList.add('active');
    }

    function closeAuthModal() {
        authModalWrap.classList.remove('active');
        currentInput = '';
        updateDots();
    }

    function appendDigit(d) {
        if (failedCount >= MAX_TRIES) return;
        if (currentInput.length < 4) {
            currentInput += d;
            playBeep(480 + (currentInput.length * 60), 'sine', 0.08);
            updateDots();
            if (currentInput.length === 4) setTimeout(submitPin, 180);
        }
    }

    function deleteDigit() {
        if (currentInput.length > 0) {
            currentInput = currentInput.slice(0, -1);
            playBeep(340, 'triangle', 0.08);
            updateDots();
        }
    }

    function submitPin() {
        if (failedCount >= MAX_TRIES) return;
        if (currentInput === AUTH_PIN) {
            isUnlocked = true;
            playBeep(523, 'triangle', 0.1);
            setTimeout(function() { playBeep(659, 'triangle', 0.12); }, 100);
            setTimeout(function() { playBeep(784, 'triangle', 0.2); }, 200);

            try { localStorage.removeItem('_younus_attempts_spent'); } catch(e) {}
            closeAuthModal();
            launchPortal();
        } else {
            failedCount++;
            playBeep(180, 'sawtooth', 0.25);
            try { localStorage.setItem('_younus_attempts_spent', String(failedCount)); } catch(e) {}

            for (let i = 0; i < 4; i++) pinDots[i].classList.add('error');
            setTimeout(function() {
                currentInput = '';
                updateDots();
                if (failedCount >= MAX_TRIES) {
                    try { localStorage.setItem('_younus_sys_locked', 'true'); } catch(e) {}
                    updateAttemptsUI();
                } else {
                    updateAttemptsUI();
                }
            }, 400);
        }
    }

    document.querySelectorAll('.key-btn[data-key]').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            appendDigit(btn.getAttribute('data-key'));
        });
    });

    const keyDel = document.getElementById('key-del');
    const keyEnter = document.getElementById('key-enter');
    if (keyDel) keyDel.addEventListener('click', function(e) { e.stopPropagation(); deleteDigit(); });
    if (keyEnter) keyEnter.addEventListener('click', function(e) { e.stopPropagation(); if (currentInput.length > 0) submitPin(); });

    window.addEventListener('keydown', function(e) {
        if (authModalWrap.classList.contains('active')) {
            if (e.key >= '0' && e.key <= '9') appendDigit(e.key);
            else if (e.key === 'Backspace') deleteDigit();
            else if (e.key === 'Enter') submitPin();
            else if (e.key === 'Escape') closeAuthModal();
        } else if (e.key === 'Escape') {
            if (isUnlocked) panicCloak();
        }
    });

    document.addEventListener('click', function(e) {
        if (isUnlocked) return;
        if (authModalWrap.classList.contains('active')) {
            if (e.target === authModalWrap) closeAuthModal();
            return;
        }
        openAuthModal();
    });

    const openPortalBtn = document.getElementById('open-portal-btn');
    if (openPortalBtn) openPortalBtn.addEventListener('click', function(e) { e.stopPropagation(); openAuthModal(); });

    // 4. Portal Navigation & Live Web Routing
    const LIVE_MIRRORS = [
        'https://cirrusbk6l.planet35.com',
        'https://drifttt82.chickenkiller.com',
        'https://flint7boq.irqsistemas.net',
        'https://onyxjbxy.sakidumarwana.com.np',
        'https://driftz9ip.abratec.com.br',
        'https://novajfag.amadeuspiano.com'
    ];

    let activeMirror = LIVE_MIRRORS[0];
    let mirrorIdx = 0;

    const portalScreen = document.getElementById('portal-screen');
    const homeDashboard = document.getElementById('home-dashboard');
    const mainIframe = document.getElementById('main-iframe');
    const omniboxInput = document.getElementById('omnibox-input');
    const nodeLabel = document.getElementById('node-label');

    function launchPortal() {
        portalScreen.classList.add('active');
        navHome();
    }

    window.navHome = function() {
        homeDashboard.style.display = 'flex';
        mainIframe.style.display = 'none';
        mainIframe.src = 'about:blank';
        omniboxInput.value = '';
        document.querySelectorAll('.bm-chip').forEach(function(c) { c.classList.remove('active'); });
        const chipHome = document.getElementById('chip-home');
        if (chipHome) chipHome.classList.add('active');
    };

    window.navUrl = function(rawUrl) {
        if (!rawUrl) return;
        let target = rawUrl.trim();

        // Direct web games & players that work 100% inside iframe
        const directPassPatterns = [
            'sz-games.github.io',
            'dddavit.github.io',
            'buildnow-gg.io',
            'vidsrc.to',
            'kdata1.com'
        ];

        let isDirect = false;
        for (let i = 0; i < directPassPatterns.length; i++) {
            if (target.indexOf(directPassPatterns[i]) !== -1) {
                isDirect = true;
                break;
            }
        }

        // YouTube handling
        if (target.indexOf('youtube.com') !== -1 || target.indexOf('youtu.be') !== -1) {
            let ytUrl = 'https://www.youtube-nocookie.com/embed?listType=search&list=trending';
            const ytMatch = target.match(/(?:v=|youtu\.be\/|embed\/)([a-zA-Z0-9_-]{11})/);
            if (ytMatch && ytMatch[1]) {
                ytUrl = 'https://www.youtube-nocookie.com/embed/' + ytMatch[1] + '?autoplay=1';
            }
            target = ytUrl;
            isDirect = true;
        }

        // TikTok handling
        if (target.indexOf('tiktok.com') !== -1) {
            target = 'https://www.tiktok.com/embed/v2/7106594312292453678';
            isDirect = true;
        }

        // Web Search Queries
        if (!target.startsWith('http://') && !target.startsWith('https://')) {
            if (target.indexOf('.') !== -1 && target.indexOf(' ') === -1) {
                target = 'https://' + target;
            } else {
                target = 'https://html.duckduckgo.com/html/?q=' + encodeURIComponent(target);
                isDirect = true;
            }
        }

        homeDashboard.style.display = 'none';
        mainIframe.style.display = 'block';
        omniboxInput.value = rawUrl;

        if (isDirect) {
            mainIframe.src = target;
        } else {
            // Route through live Scramjet unblocked gateway
            mainIframe.src = activeMirror + '/~/sj/' + encodeURIComponent(target);
        }
    };

    const btnGo = document.getElementById('btn-go');
    if (btnGo) btnGo.addEventListener('click', function() { navUrl(omniboxInput.value); });
    if (omniboxInput) {
        omniboxInput.addEventListener('keydown', function(e) {
            if (e.key === 'Enter') navUrl(omniboxInput.value);
        });
    }

    document.getElementById('btn-brand-home').addEventListener('click', navHome);
    document.getElementById('btn-home').addEventListener('click', navHome);
    document.getElementById('btn-reload').addEventListener('click', function() {
        if (mainIframe.style.display === 'block') {
            mainIframe.src = mainIframe.src;
        }
    });

    // Node Switcher
    const btnCycleNode = document.getElementById('btn-cycle-node');
    if (btnCycleNode) {
        btnCycleNode.addEventListener('click', function() {
            mirrorIdx = (mirrorIdx + 1) % LIVE_MIRRORS.length;
            activeMirror = LIVE_MIRRORS[mirrorIdx];
            const host = new URL(activeMirror).hostname.split('.')[0];
            if (nodeLabel) nodeLabel.textContent = host + ' (Live)';
            if (mainIframe.style.display === 'block' && omniboxInput.value) {
                navUrl(omniboxInput.value);
            }
        });
    }

    // Google Classroom Disguise
    let isDisguised = false;
    const btnDisguise = document.getElementById('btn-disguise');
    if (btnDisguise) {
        btnDisguise.addEventListener('click', function() {
            isDisguised = !isDisguised;
            if (isDisguised) {
                document.title = 'Classes - Google Classroom';
                const link = document.querySelector("link[rel*='icon']") || document.createElement('link');
                link.type = 'image/x-icon';
                link.rel = 'shortcut icon';
                link.href = 'https://ssl.gstatic.com/classroom/favicon.png';
                document.getElementsByTagName('head')[0].appendChild(link);
                btnDisguise.textContent = '🎭 Uncloak';
            } else {
                document.title = 'APStudy | Math and Language Arts Tutoring';
                btnDisguise.textContent = '🎭 Disguise';
            }
        });
    }

    // Panic Cloak
    function panicCloak() {
        portalScreen.classList.remove('active');
        mainIframe.src = 'about:blank';
        isUnlocked = false;
        closeAuthModal();
        if (lofiAudio && !lofiAudio.paused) {
            lofiAudio.pause();
            lofiToggle.textContent = '▶';
        }
    }
    const btnPanic = document.getElementById('btn-panic');
    if (btnPanic) btnPanic.addEventListener('click', panicCloak);

    // Lo-Fi Audio
    const lofiAudio = document.getElementById('lofi-audio');
    const lofiToggle = document.getElementById('lofi-toggle');
    const lofiStatus = document.getElementById('lofi-status');
    if (lofiToggle && lofiAudio) {
        lofiToggle.addEventListener('click', function() {
            if (lofiAudio.paused) {
                lofiAudio.play().then(function() {
                    lofiToggle.textContent = '⏸';
                    lofiStatus.textContent = 'Streaming live chill Lo-Fi beats...';
                }).catch(function() {
                    lofiStatus.textContent = 'Click again to permit audio playback';
                });
            } else {
                lofiAudio.pause();
                lofiToggle.textContent = '▶';
                lofiStatus.textContent = 'Paused';
            }
        });
    }
})();
